 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Fill internal holes in horizontal bars and project the hole's color upward.
    rays = []
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v]
        # Horizontal bars are dense; ignore sparse lower marker strokes.
        if len(nz) < 5:
            continue
        for c in range(nz[0] + 1, nz[-1]):
            if row[c] == 0:
                left = next((row[k] for k in range(c - 1, -1, -1) if row[k]), 0)
                right = next((row[k] for k in range(c + 1, w) if row[k]), 0)
                if left and right and left != right:
                    out[r][c] = right
                else:
                    out[r][c] = left or right
                # Only a one-cell missing pixel bracketed by matching colors
                # shoots a ray toward the top.
                if 0 < c < w - 1 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                    rays.append((r, c, row[c - 1]))
    for r, c, color in rays:
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1
    # Sparse vertical marker strokes along the bottom project upward until
    # reaching a colored bar, without overwriting it.
    for c in range(w):
        seed = next((r for r in range(h - 1, max(-1, h - 3), -1) if grid[r][c]), None)
        if seed is None:
            continue
        color = grid[seed][c]
        rr = seed - 1
        while rr >= 0 and grid[rr][c] == color:
            rr -= 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1
    return out
